def countArrangementBitmask(n: int) -> int:
    memo = {}
    def dfs(mask):
        if mask == (1 << n) - 1: return 1
        if mask in memo: return memo[mask]
        pos = bin(mask).count('1') + 1
        ans = 0
        for num in range(1, n + 1):
            if not (mask & (1 << (num - 1))):
                if num % pos == 0 or pos % num == 0:
                    ans += dfs(mask | (1 << (num - 1)))
        memo[mask] = ans
        return ans
    return dfs(0)

